(595,420,$mw$85F63FD08B534850AB83F8802F3B36C67FE21016ED1557222DEE85DFB8D39DD4$mw$,$mw$69706e0e55963e47b419d450bd2ef2c8$mw$,$mw$$mw$,$mw${"Id":420,"StageId":1,"CategoryId":21,"Points":10,"TitleAr":"جمع كسور مختلفة المقامات باستخدام مقام مشترك","TitleEn":"Add unlike fractions using a common denominator","QuestionTextAr":"احسب $\\frac14+\\frac38$.","QuestionTextEn":"Compute $\\frac14+\\frac38$.","DetailedSolutionAr":"نحوّل الربع إلى أثمان: $\\frac14=\\frac28$، ثم $\\frac28+\\frac38=\\frac58$.","DetailedSolutionEn":"Convert quarters to eighths: $\\frac14=\\frac28$, then add to get $\\frac58$.","YoutubeSolutionUrl":null,"EditorialDetailsJson":null,"Options":[{"Id":1669,"Order":1,"LatexCode":"\\frac4{12}","IsCorrect":false},{"Id":1670,"Order":2,"LatexCode":"\\frac78","IsCorrect":false},{"Id":1671,"Order":3,"LatexCode":"\\frac58","IsCorrect":true},{"Id":1672,"Order":4,"LatexCode":"\\frac48","IsCorrect":false}]}$mw$::jsonb,$mw${"Hints":[{"Ar":"هل المقامان متساويان؟","En":"Are the denominators equal?"},{"Ar":"حوّل الكسر الأول إلى أثمان ثم اجمع البسطين.","En":"Convert the first fraction into eighths, then add the numerators."}],"Title":{"Ar":"جمع كسور مختلفة المقامات باستخدام مقام مشترك","En":"Add unlike fractions using a common denominator"},"Points":10,"Options":[{"Reason":{"Ar":"جمع البسطين والمقامين مباشرة يعطي 4/12 وهو غير صحيح.","En":"Adding numerators and denominators directly gives 4/12, which is invalid."},"ErrorType":"add-denominators","IsCorrect":false,"LatexCode":"\\frac4{12}"},{"Reason":{"Ar":"7/8 لا يساوي مجموع البسطين 2 و3 بعد توحيد المقام.","En":"7/8 does not use the sum of the converted numerators 2 and 3."},"ErrorType":"numerator-error","IsCorrect":false,"LatexCode":"\\frac78"},{"Reason":null,"ErrorType":"","IsCorrect":true,"LatexCode":"\\frac58"},{"Reason":{"Ar":"4/8 يجمع 1 و3 دون تحويل الربع إلى 2/8.","En":"4/8 adds 1 and 3 without converting the quarter."},"ErrorType":"missing-conversion","IsCorrect":false,"LatexCode":"\\frac48"}],"StageId":1,"Question":{"Ar":"احسب $\\frac14+\\frac38$.","En":"Compute $\\frac14+\\frac38$."},"Solution":{"Idea":{"Ar":"قانون جمع الكسور المتجانسة: $a/d+b/d=(a+b)/d$ عندما $d\\ne0$. نوحّد المقامات أولاً.","En":"Common-denominator rule: $a/d+b/d=(a+b)/d$ for $d\\ne0$. First use equal denominators."},"Unit":{"Ar":"بلا وحدة قياس","En":"Dimensionless"},"Steps":[{"Ar":"المقام المشترك 8؛ نضرب بسط ومقام $\\frac14$ في 2 فنحصل على $\\frac28$.","En":"Use common denominator 8; multiply both numerator and denominator of $\\frac14$ by 2 to obtain $\\frac28$."},{"Ar":"نجمع $2+3=5$ أجزاء من ثمانية، فنحصل على $\\frac58$.","En":"Add $2+3=5$ eighths to obtain $\\frac58$."}],"Result":{"Ar":"$\\frac58$","En":"$\\frac58$"},"CommonError":{"Ar":"لا نجمع المقامين عند جمع الكسور.","En":"Do not add denominators when adding fractions."},"FormulaLatex":"\\frac{a}{d}+\\frac{b}{d}=\\frac{a+b}{d},\\quad d\\ne0","Substitution":{"Ar":"$\\frac14=\\frac28$، ثم $\\frac28+\\frac38$","En":"$\\frac14=\\frac28$, then $\\frac28+\\frac38$"},"Verification":{"Ar":"$0.25+0.375=0.625=5/8$","En":"$0.25+0.375=0.625=5/8$"}},"TrackIds":[5],"CategoryId":21,"PrimarySkillId":95,"DifficultyLevel":1,"SecondarySkillIds":[]}$mw$::jsonb,$mw${"DifficultyLevel":1,"Hints":[{"Ar":"هل المقامان متساويان؟","En":"Are the denominators equal?"},{"Ar":"حوّل الكسر الأول إلى أثمان ثم اجمع البسطين.","En":"Convert the first fraction into eighths, then add the numerators."}],"Solution":{"Idea":{"Ar":"قانون جمع الكسور المتجانسة: $a/d+b/d=(a+b)/d$ عندما $d\\ne0$. نوحّد المقامات أولاً.","En":"Common-denominator rule: $a/d+b/d=(a+b)/d$ for $d\\ne0$. First use equal denominators."},"Unit":{"Ar":"بلا وحدة قياس","En":"Dimensionless"},"Steps":[{"Ar":"المقام المشترك 8؛ نضرب بسط ومقام $\\frac14$ في 2 فنحصل على $\\frac28$.","En":"Use common denominator 8; multiply both numerator and denominator of $\\frac14$ by 2 to obtain $\\frac28$."},{"Ar":"نجمع $2+3=5$ أجزاء من ثمانية، فنحصل على $\\frac58$.","En":"Add $2+3=5$ eighths to obtain $\\frac58$."}],"Result":{"Ar":"$\\frac58$","En":"$\\frac58$"},"CommonError":{"Ar":"لا نجمع المقامين عند جمع الكسور.","En":"Do not add denominators when adding fractions."},"FormulaLatex":"\\frac{a}{d}+\\frac{b}{d}=\\frac{a+b}{d},\\quad d\\ne0","Substitution":{"Ar":"$\\frac14=\\frac28$، ثم $\\frac28+\\frac38$","En":"$\\frac14=\\frac28$, then $\\frac28+\\frac38$"},"Verification":{"Ar":"$0.25+0.375=0.625=5/8$","En":"$0.25+0.375=0.625=5/8$"}},"Distractors":[{"ErrorType":"add-denominators","Reason":{"Ar":"جمع البسطين والمقامين مباشرة يعطي 4/12 وهو غير صحيح.","En":"Adding numerators and denominators directly gives 4/12, which is invalid."},"Order":1},{"ErrorType":"numerator-error","Reason":{"Ar":"7/8 لا يساوي مجموع البسطين 2 و3 بعد توحيد المقام.","En":"7/8 does not use the sum of the converted numerators 2 and 3."},"Order":2},{"ErrorType":"","Reason":null,"Order":3},{"ErrorType":"missing-conversion","Reason":{"Ar":"4/8 يجمع 1 و3 دون تحويل الربع إلى 2/8.","En":"4/8 adds 1 and 3 without converting the quarter."},"Order":4}]}$mw$,$mw$قانون جمع الكسور المتجانسة: $a/d+b/d=(a+b)/d$ عندما $d\ne0$. نوحّد المقامات أولاً.

$\frac{a}{d}+\frac{b}{d}=\frac{a+b}{d},\quad d\ne0$

1. المقام المشترك 8؛ نضرب بسط ومقام $\frac14$ في 2 فنحصل على $\frac28$.

2. نجمع $2+3=5$ أجزاء من ثمانية، فنحصل على $\frac58$.

$\frac14=\frac28$، ثم $\frac28+\frac38$

$\frac58$ بلا وحدة قياس

$0.25+0.375=0.625=5/8$

لا نجمع المقامين عند جمع الكسور.$mw$,$mw$Common-denominator rule: $a/d+b/d=(a+b)/d$ for $d\ne0$. First use equal denominators.

$\frac{a}{d}+\frac{b}{d}=\frac{a+b}{d},\quad d\ne0$

1. Use common denominator 8; multiply both numerator and denominator of $\frac14$ by 2 to obtain $\frac28$.

2. Add $2+3=5$ eighths to obtain $\frac58$.

$\frac14=\frac28$, then $\frac28+\frac38$

$\frac58$ Dimensionless

$0.25+0.375=0.625=5/8$

Do not add denominators when adding fractions.$mw$),
(596,421,$mw$BC066E0F34CE04D7D30F265C21AA5B3D7ADC06F52607AC413626C624236373D0$mw$,$mw$8605c20301976273dcc3e11a2d9686e0$mw$,$mw$$mw$,$mw${"Id":421,"StageId":1,"CategoryId":21,"Points":10,"TitleAr":"إيجاد كسر مكافئ بمقام محدد","TitleEn":"Find an equivalent fraction with a specified denominator","QuestionTextAr":"ما الكسر المكافئ لـ $\\frac{3}{4}$ عندما يكون المقام 12؟","QuestionTextEn":"Which fraction is equivalent to $\\frac{3}{4}$ with denominator 12?","DetailedSolutionAr":"نضرب البسط والمقام في 3: $\\frac{3\\times3}{4\\times3}=\\frac{9}{12}$.","DetailedSolutionEn":"Multiply numerator and denominator by 3: $\\frac{3\\times3}{4\\times3}=\\frac{9}{12}$.","YoutubeSolutionUrl":null,"EditorialDetailsJson":null,"Options":[{"Id":1673,"Order":1,"LatexCode":"\\frac{6}{12}","IsCorrect":false},{"Id":1674,"Order":2,"LatexCode":"\\frac{3}{12}","IsCorrect":false},{"Id":1675,"Order":3,"LatexCode":"\\frac{12}{9}","IsCorrect":false},{"Id":1676,"Order":4,"LatexCode":"\\frac{9}{12}","IsCorrect":true}]}$mw$::jsonb,$mw${"Hints":[{"Ar":"كيف يصبح المقام أربعة مساويًا لاثني عشر؟","En":"How can the denominator four become twelve?"},{"Ar":"اضرب البسط والمقام بالمعامل نفسه.","En":"Multiply numerator and denominator by the same factor."}],"Title":{"Ar":"إيجاد كسر مكافئ بمقام محدد","En":"Find an equivalent fraction with a specified denominator"},"Points":10,"Options":[{"Reason":{"Ar":"6/12 يساوي النصف، لا ثلاثة أرباع.","En":"6/12 equals one half, not three quarters."},"ErrorType":"scale-mismatch","IsCorrect":false,"LatexCode":"\\frac{6}{12}"},{"Reason":{"Ar":"3/12 يغيّر المقام دون البسط.","En":"3/12 changes the denominator but not the numerator."},"ErrorType":"denominator-only","IsCorrect":false,"LatexCode":"\\frac{3}{12}"},{"Reason":{"Ar":"12/9 مقامه ليس 12 وقيمته أكبر من واحد.","En":"12/9 has the wrong denominator and is greater than one."},"ErrorType":"inversion","IsCorrect":false,"LatexCode":"\\frac{12}{9}"},{"Reason":null,"ErrorType":"","IsCorrect":true,"LatexCode":"\\frac{9}{12}"}],"StageId":1,"Question":{"Ar":"ما الكسر المكافئ لـ $\\frac{3}{4}$ عندما يكون المقام 12؟","En":"Which fraction is equivalent to $\\frac{3}{4}$ with denominator 12?"},"Solution":{"Idea":{"Ar":"خاصية الكسور المتكافئة: $a/b=ka/kb$ عندما $b,k\\ne0$. للحصول على المقام 12 نختار $k=12/4=3$.","En":"Equivalent fractions: $a/b=ka/kb$ for nonzero $b,k$. Choose $k=12/4=3$ to obtain denominator 12."},"Unit":{"Ar":"بلا وحدة قياس","En":"Dimensionless"},"Steps":[{"Ar":"معامل التوسيع هو $12\\div4=3$.","En":"The scale factor is $12\\div4=3$."},{"Ar":"نضرب البسط والمقام في 3: $\\frac{3\\times3}{4\\times3}=\\frac9{12}$.","En":"Multiply numerator and denominator by 3: $\\frac{3\\times3}{4\\times3}=\\frac9{12}$."}],"Result":{"Ar":"$\\frac9{12}$","En":"$\\frac9{12}$"},"CommonError":{"Ar":"تغيير المقام وحده يغيّر قيمة الكسر.","En":"Changing only the denominator changes the fraction."},"FormulaLatex":"\\frac{a}{b}=\\frac{ka}{kb},\\quad b,k\\ne0","Substitution":{"Ar":"$k=3,\\quad \\frac{3\\times3}{4\\times3}$","En":"$k=3,\\quad \\frac{3\\times3}{4\\times3}$"},"Verification":{"Ar":"$9\\times4=12\\times3=36$","En":"$9\\times4=12\\times3=36$"}},"TrackIds":[4],"CategoryId":21,"PrimarySkillId":96,"DifficultyLevel":1,"SecondarySkillIds":[]}$mw$::jsonb,$mw${"DifficultyLevel":1,"Hints":[{"Ar":"كيف يصبح المقام أربعة مساويًا لاثني عشر؟","En":"How can the denominator four become twelve?"},{"Ar":"اضرب البسط والمقام بالمعامل نفسه.","En":"Multiply numerator and denominator by the same factor."}],"Solution":{"Idea":{"Ar":"خاصية الكسور المتكافئة: $a/b=ka/kb$ عندما $b,k\\ne0$. للحصول على المقام 12 نختار $k=12/4=3$.","En":"Equivalent fractions: $a/b=ka/kb$ for nonzero $b,k$. Choose $k=12/4=3$ to obtain denominator 12."},"Unit":{"Ar":"بلا وحدة قياس","En":"Dimensionless"},"Steps":[{"Ar":"معامل التوسيع هو $12\\div4=3$.","En":"The scale factor is $12\\div4=3$."},{"Ar":"نضرب البسط والمقام في 3: $\\frac{3\\times3}{4\\times3}=\\frac9{12}$.","En":"Multiply numerator and denominator by 3: $\\frac{3\\times3}{4\\times3}=\\frac9{12}$."}],"Result":{"Ar":"$\\frac9{12}$","En":"$\\frac9{12}$"},"CommonError":{"Ar":"تغيير المقام وحده يغيّر قيمة الكسر.","En":"Changing only the denominator changes the fraction."},"FormulaLatex":"\\frac{a}{b}=\\frac{ka}{kb},\\quad b,k\\ne0","Substitution":{"Ar":"$k=3,\\quad \\frac{3\\times3}{4\\times3}$","En":"$k=3,\\quad \\frac{3\\times3}{4\\times3}$"},"Verification":{"Ar":"$9\\times4=12\\times3=36$","En":"$9\\times4=12\\times3=36$"}},"Distractors":[{"ErrorType":"scale-mismatch","Reason":{"Ar":"6/12 يساوي النصف، لا ثلاثة أرباع.","En":"6/12 equals one half, not three quarters."},"Order":1},{"ErrorType":"denominator-only","Reason":{"Ar":"3/12 يغيّر المقام دون البسط.","En":"3/12 changes the denominator but not the numerator."},"Order":2},{"ErrorType":"inversion","Reason":{"Ar":"12/9 مقامه ليس 12 وقيمته أكبر من واحد.","En":"12/9 has the wrong denominator and is greater than one."},"Order":3},{"ErrorType":"","Reason":null,"Order":4}]}$mw$,$mw$خاصية الكسور المتكافئة: $a/b=ka/kb$ عندما $b,k\ne0$. للحصول على المقام 12 نختار $k=12/4=3$.

$\frac{a}{b}=\frac{ka}{kb},\quad b,k\ne0$

1. معامل التوسيع هو $12\div4=3$.

2. نضرب البسط والمقام في 3: $\frac{3\times3}{4\times3}=\frac9{12}$.

$k=3,\quad \frac{3\times3}{4\times3}$

$\frac9{12}$ بلا وحدة قياس

$9\times4=12\times3=36$

تغيير المقام وحده يغيّر قيمة الكسر.$mw$,$mw$Equivalent fractions: $a/b=ka/kb$ for nonzero $b,k$. Choose $k=12/4=3$ to obtain denominator 12.

$\frac{a}{b}=\frac{ka}{kb},\quad b,k\ne0$

1. The scale factor is $12\div4=3$.

2. Multiply numerator and denominator by 3: $\frac{3\times3}{4\times3}=\frac9{12}$.

$k=3,\quad \frac{3\times3}{4\times3}$

$\frac9{12}$ Dimensionless

$9\times4=12\times3=36$

Changing only the denominator changes the fraction.$mw$),
(597,422,$mw$445B95D5835954C51E245C24A1B4580514328016CD1A87D878318018E19E4AE4$mw$,$mw$d1b3275a91e87bca1bdef97e0fe75cae$mw$,$mw$$mw$,$mw${"Id":422,"StageId":1,"CategoryId":21,"Points":10,"TitleAr":"مقارنة كسر اعتيادي مع عدد عشري","TitleEn":"Compare a common fraction with a decimal","QuestionTextAr":"أي علاقة صحيحة بين $0.6$ و$\\frac35$؟","QuestionTextEn":"Which comparison of $0.6$ and $\\frac35$ is correct?","DetailedSolutionAr":"المبدأ المستخدم: لمقارنة كسر بعدد عشري نحول الاثنين إلى تمثيل عددي واحد. نحسب قيمة الكسر بالقسمة: 3 ÷ 5 = 0.6. العدد الآخر يساوي 0.6 أيضاً، لذلك العلاقة الصحيحة 0.6 = 3/5. التحقق: 0.6 × 5 = 3.","DetailedSolutionEn":"Rule used: Compare a fraction with a decimal by converting both to the same representation. Divide 3 by 5 to obtain 0.6. Since the other value is also 0.6, the correct comparison is 0.6 = 3/5. Check: 0.6 × 5 = 3.","YoutubeSolutionUrl":null,"EditorialDetailsJson":null,"Options":[{"Id":1677,"Order":1,"LatexCode":"0.6=\\frac35","IsCorrect":true},{"Id":1678,"Order":2,"LatexCode":"0.6>\\frac35","IsCorrect":false},{"Id":1679,"Order":3,"LatexCode":"0.6<\\frac35","IsCorrect":false},{"Id":1680,"Order":4,"LatexCode":"0.6=\\frac53","IsCorrect":false}]}$mw$::jsonb,$mw${"Hints":[{"Ar":"حوّل الكسر إلى عدد عشري.","En":"Convert the fraction to a decimal."},{"Ar":"اقسم البسط على المقام ثم قارن.","En":"Divide the numerator by the denominator, then compare."}],"Title":{"Ar":"مقارنة كسر اعتيادي مع عدد عشري","En":"Compare a common fraction with a decimal"},"Points":10,"Options":[{"Reason":null,"ErrorType":"","IsCorrect":true,"LatexCode":"0.6=\\frac35"},{"Reason":{"Ar":"الفرق $0.6-\\frac35=0$؛ فلا يمكن أن تكون القيمة الأولى أكبر.","En":"The difference $0.6-\\frac35=0$, so the first value is not greater."},"ErrorType":"incorrect-option","IsCorrect":false,"LatexCode":"0.6>\\frac35"},{"Reason":{"Ar":"الفرق $\\frac35-0.6=0$؛ فلا يمكن أن تكون القيمة الثانية أكبر.","En":"The difference $\\frac35-0.6=0$, so the second value is not greater."},"ErrorType":"incorrect-option","IsCorrect":false,"LatexCode":"0.6<\\frac35"},{"Reason":{"Ar":"قلب الكسر يعطي قيمة أكبر من الواحد، بينما 0.6 أقل من الواحد.","En":"Inverting the fraction gives a value above one, whereas 0.6 is below one."},"ErrorType":"incorrect-option","IsCorrect":false,"LatexCode":"0.6=\\frac53"}],"StageId":1,"Question":{"Ar":"أي علاقة صحيحة بين $0.6$ و$\\frac35$؟","En":"Which comparison of $0.6$ and $\\frac35$ is correct?"},"Solution":{"Idea":{"Ar":"نقارن العدد العشري والكسر بعد توحيد تمثيلهما.","En":"Compare the decimal and fraction in a common representation."},"Unit":{"Ar":"بلا وحدة قياس","En":"Dimensionless"},"Steps":[{"Ar":"نضرب بسط ومقام $\\frac35$ في 2 فنحصل على $\\frac6{10}$.","En":"Multiply numerator and denominator of $\\frac35$ by 2 to get $\\frac6{10}$."},{"Ar":"ستة أعشار تساوي $0.6$؛ إذن القيمتان متساويتان.","En":"Six tenths equal $0.6$, so the two values are equal."}],"Result":{"Ar":"$0.6=\\frac35$","En":"$0.6=\\frac35$"},"CommonError":{"Ar":"لا تعكس البسط والمقام.","En":"Do not invert the numerator and denominator."},"FormulaLatex":"\\frac ab=a\\div b\\quad(b\\ne0)","Substitution":{"Ar":"$3\\div5=0.6$","En":"$3\\div5=0.6$"},"Verification":{"Ar":"$0.6\\times5=3$","En":"$0.6\\times5=3$"}},"TrackIds":[5],"CategoryId":21,"PrimarySkillId":94,"DifficultyLevel":1,"SecondarySkillIds":[]}$mw$::jsonb,$mw${"DifficultyLevel":1,"Hints":[{"Ar":"حوّل الكسر إلى عدد عشري.","En":"Convert the fraction to a decimal."},{"Ar":"اقسم البسط على المقام ثم قارن.","En":"Divide the numerator by the denominator, then compare."}],"Solution":{"Idea":{"Ar":"نقارن العدد العشري والكسر بعد توحيد تمثيلهما.","En":"Compare the decimal and fraction in a common representation."},"Unit":{"Ar":"بلا وحدة قياس","En":"Dimensionless"},"Steps":[{"Ar":"نضرب بسط ومقام $\\frac35$ في 2 فنحصل على $\\frac6{10}$.","En":"Multiply numerator and denominator of $\\frac35$ by 2 to get $\\frac6{10}$."},{"Ar":"ستة أعشار تساوي $0.6$؛ إذن القيمتان متساويتان.","En":"Six tenths equal $0.6$, so the two values are equal."}],"Result":{"Ar":"$0.6=\\frac35$","En":"$0.6=\\frac35$"},"CommonError":{"Ar":"لا تعكس البسط والمقام.","En":"Do not invert the numerator and denominator."},"FormulaLatex":"\\frac ab=a\\div b\\quad(b\\ne0)","Substitution":{"Ar":"$3\\div5=0.6$","En":"$3\\div5=0.6$"},"Verification":{"Ar":"$0.6\\times5=3$","En":"$0.6\\times5=3$"}},"Distractors":[{"ErrorType":"","Reason":null,"Order":1},{"ErrorType":"incorrect-option","Reason":{"Ar":"الفرق $0.6-\\frac35=0$؛ فلا يمكن أن تكون القيمة الأولى أكبر.","En":"The difference $0.6-\\frac35=0$, so the first value is not greater."},"Order":2},{"ErrorType":"incorrect-option","Reason":{"Ar":"الفرق $\\frac35-0.6=0$؛ فلا يمكن أن تكون القيمة الثانية أكبر.","En":"The difference $\\frac35-0.6=0$, so the second value is not greater."},"Order":3},{"ErrorType":"incorrect-option","Reason":{"Ar":"قلب الكسر يعطي قيمة أكبر من الواحد، بينما 0.6 أقل من الواحد.","En":"Inverting the fraction gives a value above one, whereas 0.6 is below one."},"Order":4}]}$mw$,$mw$نقارن العدد العشري والكسر بعد توحيد تمثيلهما.

$\frac ab=a\div b\quad(b\ne0)$

1. نضرب بسط ومقام $\frac35$ في 2 فنحصل على $\frac6{10}$.

2. ستة أعشار تساوي $0.6$؛ إذن القيمتان متساويتان.

$3\div5=0.6$

$0.6=\frac35$ بلا وحدة قياس

$0.6\times5=3$

لا تعكس البسط والمقام.$mw$,$mw$Compare the decimal and fraction in a common representation.

$\frac ab=a\div b\quad(b\ne0)$

1. Multiply numerator and denominator of $\frac35$ by 2 to get $\frac6{10}$.

2. Six tenths equal $0.6$, so the two values are equal.

$3\div5=0.6$

$0.6=\frac35$ Dimensionless

$0.6\times5=3$

Do not invert the numerator and denominator.$mw$),
(598,423,$mw$86D8D02E6B0CDE9CD762C9FD896C62FE1C4AD29762BFBDD9D1B1ACE995E9DBC6$mw$,$mw$7112028e7b67d193869f90332ca9c7a0$mw$,$mw$$mw$,$mw${"Id":423,"StageId":1,"CategoryId":21,"Points":10,"TitleAr":"حساب كسر من مجموعة عناصر","TitleEn":"Find a fractional part of a collection","QuestionTextAr":"في مكتبة 36 كتاباً، ثلثاها كتب علمية. كم كتاباً علمياً يوجد؟","QuestionTextEn":"A library has 36 books. Two-thirds are science books. How many science books are there?","DetailedSolutionAr":"القانون المستخدم: لإيجاد كسر من كمية نضرب الكمية في الكسر. الكتب العلمية = (2/3) × 36؛ نقسم 36 على 3 أولاً فنحصل على 12، ثم نضرب في 2: 12 × 2 = 24 كتاباً علمياً. التحقق: 24 من 36 يساوي ثلثي المجموع.","DetailedSolutionEn":"Rule used: To find a fraction of a quantity, multiply the total by the fraction. Science books = (2/3) × 36. First 36 ÷ 3 = 12, then 12 × 2 = 24 books. Check: 24/36 = 2/3.","YoutubeSolutionUrl":null,"EditorialDetailsJson":null,"Options":[{"Id":1681,"Order":1,"LatexCode":"27","IsCorrect":false},{"Id":1682,"Order":2,"LatexCode":"24","IsCorrect":true},{"Id":1683,"Order":3,"LatexCode":"18","IsCorrect":false},{"Id":1684,"Order":4,"LatexCode":"12","IsCorrect":false}]}$mw$::jsonb,$mw${"Hints":[{"Ar":"الثلثان يعنيان جزأين من ثلاثة أجزاء متساوية.","En":"Two thirds means two of three equal parts."},{"Ar":"اقسم المجموع على ثلاثة ثم ضاعف الجزء.","En":"Divide the total by three, then double the part."}],"Title":{"Ar":"حساب كسر من مجموعة عناصر","En":"Find a fractional part of a collection"},"Points":10,"Options":[{"Reason":{"Ar":"العدد 27 من 36 لا يحقق نسبة الثلثين؛ الضرب التبادلي يعطي 81 مقابل 72.","En":"27 out of 36 is not two thirds: cross multiplication gives 81 versus 72."},"ErrorType":"incorrect-option","IsCorrect":false,"LatexCode":"27"},{"Reason":null,"ErrorType":"","IsCorrect":true,"LatexCode":"24"},{"Reason":{"Ar":"العدد 18 من 36 لا يحقق نسبة الثلثين؛ الضرب التبادلي يعطي 54 مقابل 72.","En":"18 out of 36 is not two thirds: cross multiplication gives 54 versus 72."},"ErrorType":"i